:root {
  --bg: #f4f1de;
  --card-bg: #ffffff;
  --text: #3d405b;
  --primary: #e07a5f;
  --primary-dark: #c0604a;
  --secondary: #81b29a;
  --border: #dcdcdc;
  --radius: 12px;
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  margin: 16px auto;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 4px;
  color: var(--primary);
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 8px;
  color: var(--text);
}

header {
  margin-bottom: 20px;
}

#remaining {
  font-size: 1rem;
  color: var(--secondary);
  font-weight: 600;
}

form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 24px;
  align-items: flex-end;
}

.input-group {
  display: flex;
  flex-direction: column;
  flex: 1 1 140px;
}

.input-group label {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 4px;
}

input {
  font: inherit;
  padding: 10px 12px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(224, 122, 95, 0.3);
}

input:hover {
  border-color: var(--secondary);
}

button {
  font: inherit;
  font-weight: 600;
  padding: 10px 20px;
  border: none;
  border-radius: 8px;
  background: var(--primary);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-height: 44px;
  touch-action: manipulation;
}

button:hover {
  background: var(--primary-dark);
}

button:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

button:disabled {
  background: #ccc;
  cursor: not-allowed;
  transform: none;
}

#add-btn {
  flex: 0 0 auto;
  align-self: flex-end;
  margin-bottom: 1px; /* align with inputs */
}

.item-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.item-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 8px;
  border-bottom: 1px solid var(--border);
  transition: background 0.2s;
}

.item-list li:last-child {
  border-bottom: none;
}

.item-list li:hover {
  background: #fafafa;
}

.item-list li .item-name {
  flex: 1;
  font-weight: 500;
  word-break: break-word;
}

.item-list li .item-qty {
  font-size: 0.875rem;
  color: var(--secondary);
  font-weight: 600;
  white-space: nowrap;
}

.item-list li input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--primary);
  cursor: pointer;
  flex-shrink: 0;
}

.item-list li input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 2px;
}

#bought-list li {
  text-decoration: line-through;
  opacity: 0.7;
}

#bought-list .item-name {
  text-decoration: line-through;
}

.bought-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 8px;
}

.bought-header h2 {
  margin-bottom: 0;
}

#clear-bought {
  background: var(--secondary);
  font-size: 0.875rem;
  padding: 8px 16px;
}

#clear-bought:hover:not(:disabled) {
  background: #6a9c83;
}

.empty-msg {
  color: #999;
  font-style: italic;
  padding: 12px 0;
  text-align: center;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  form {
    flex-direction: column;
    align-items: stretch;
  }
  #add-btn {
    align-self: stretch;
  }
}

'use strict';

const state = {
  items: [
    { id: 1, name: 'Milk', qty: 2, bought: false },
    { id: 2, name: 'Bread', qty: 1, bought: false },
    { id: 3, name: 'Eggs', qty: 12, bought: true },
  ],
  nextId: 4,
};

const addForm = document.getElementById('add-form');
const itemNameInput = document.getElementById('item-name');
const itemQtyInput = document.getElementById('item-qty');
const activeList = document.getElementById('active-list');
const boughtList = document.getElementById('bought-list');
const remainingEl = document.getElementById('remaining');
const emptyActive = document.getElementById('empty-active');
const emptyBought = document.getElementById('empty-bought');
const clearBoughtBtn = document.getElementById('clear-bought');

function render() {
  const activeItems = state.items.filter(i => !i.bought);
  const boughtItems = state.items.filter(i => i.bought);

  activeList.innerHTML = '';
  boughtList.innerHTML = '';

  activeItems.forEach(item => {
    const li = document.createElement('li');
    li.dataset.id = item.id;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `bought-${item.id}`;
    checkbox.checked = false;
    checkbox.setAttribute('aria-label', `Mark ${item.name} as bought`);
    checkbox.addEventListener('change', () => toggleBought(item.id));

    const nameSpan = document.createElement('span');
    nameSpan.className = 'item-name';
    nameSpan.textContent = item.name;

    const qtySpan = document.createElement('span');
    qtySpan.className = 'item-qty';
    qtySpan.textContent = `×${item.qty}`;

    li.append(checkbox, nameSpan, qtySpan);
    activeList.appendChild(li);
  });

  boughtItems.forEach(item => {
    const li = document.createElement('li');
    li.dataset.id = item.id;

    const nameSpan = document.createElement('span');
    nameSpan.className = 'item-name';
    nameSpan.textContent = item.name;

    const qtySpan = document.createElement('span');
    qtySpan.className = 'item-qty';
    qtySpan.textContent = `×${item.qty}`;

    li.append(nameSpan, qtySpan);
    boughtList.appendChild(li);
  });

  const remaining = activeItems.length;
  remainingEl.textContent = `${remaining} item${remaining !== 1 ? 's' : ''} remaining`;

  emptyActive.hidden = activeItems.length > 0;
  emptyBought.hidden = boughtItems.length > 0;
  clearBoughtBtn.disabled = boughtItems.length === 0;
}

function addItem(name, qty) {
  const trimmed = name.trim();
  if (!trimmed) return;
  const quantity = Math.max(1, parseInt(qty, 10) || 1);
  state.items.push({
    id: state.nextId++,
    name: trimmed,
    qty: quantity,
    bought: false,
  });
  render();
}

function toggleBought(id) {
  const item = state.items.find(i => i.id === id);
  if (item) {
    item.bought = !item.bought;
    // Move the item to the end of the array so it appears at the bottom of the bought list
    state.items = state.items.filter(i => i.id !== id);
    state.items.push(item);
    render();
  }
}

function clearBought() {
  state.items = state.items.filter(i => !i.bought);
  render();
}

addForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = itemNameInput.value;
  const qty = itemQtyInput.value;
  if (!name.trim()) return;
  addItem(name, qty);
  itemNameInput.value = '';
  itemQtyInput.value = '1';
  itemNameInput.focus();
});

clearBoughtBtn.addEventListener('click', clearBought);

render();
